package com.example.myweatherforecast.navigationsimport androidx.compose.runtime.Composableimport androidx.navigation.compose.NavHostimport androidx.navigation.compose.composableimport androidx.navigation.compose.rememberNavControllerimport com.example.myweatherforecast.views.WeatherSplashScreen@Composablefun WeatherNavigation() {    val navController = rememberNavController()    NavHost(        navController = navController,        startDestination = WeatherScreens.SplashScreen.name    ) {        composable(WeatherScreens.SplashScreen.name) {            WeatherSplashScreen(navController = navController)        }        composable(WeatherScreens.MainScreen.name) {            // TODO: MainScreen(navController = navController)        }        composable(WeatherScreens.AboutScreen.name) {            // TODO: AboutScreen(navController = navController)        }        composable(WeatherScreens.FavoriteScreen.name) {            // TODO: FavoriteScreen(navController = navController)        }        composable(WeatherScreens.SettingsScreen.name) {            // TODO: SettingsScreen(navController = navController)        }    }}